export function insertGroups() {
  const out = [];
  for (const o of CATALOG) {
    const last = out[out.length - 1];
    if (!last || last.label !== o.group) out.push({ label: o.group, items: [] });
    out[out.length - 1].items.push({ kind: o.kind, label: o.label });
  }
  return out;
}

